<?php
namespace App\Http\Controllers;use App\Models\ClassSchedule;use Illuminate\Http\Request;use Illuminate\Validation\Rule;use Illuminate\Validation\ValidationException;class ScheduleController extends Controller{private function base(Request $r){$u=$r->user();$q=ClassSchedule::with(['subject','section','room']);if($u->role==='student')$q->where('status','published')->where('section_id',$u->section_id);elseif($u->role==='teacher')$q->where('status','published')->where('instructor_name',$u->instructor_name?:$u->name);elseif($r->filled('status'))$q->where('status',$r->query('status'));if($r->filled('day'))$q->where('day',$r->query('day'));if($r->filled('search')){$term='%'.$r->query('search').'%';$q->where(fn($w)=>$w->whereHas('subject',fn($s)=>$s->where('title','like',$term)->orWhere('subject_code','like',$term))->orWhere('instructor_name','like',$term));}$q->orderByRaw("CASE day WHEN 'Monday' THEN 1 WHEN 'Tuesday' THEN 2 WHEN 'Wednesday' THEN 3 WHEN 'Thursday' THEN 4 WHEN 'Friday' THEN 5 WHEN 'Saturday' THEN 6 ELSE 7 END")->orderBy('start_time');return $q;}public function index(Request $r){return $this->base($r)->paginate(min(max((int)$r->query('per_page',50),1),100));}public function show(Request $r,ClassSchedule $schedule){$u=$r->user();if($u->role==='student'&&($schedule->status!=='published'||$schedule->section_id!==$u->section_id))abort(403);if($u->role==='teacher'&&($schedule->status!=='published'||$schedule->instructor_name!==($u->instructor_name?:$u->name)))abort(403);return $schedule->load(['subject','section','room']);}private function validated(Request $r,?ClassSchedule $ignore=null){$d=$r->validate(['subject_id'=>'nullable|exists:subjects,id','section_id'=>'required|exists:sections,id','room_id'=>'required|exists:rooms,id','custom_name'=>'nullable|string|max:180','instructor_name'=>'required|string|max:120','day'=>['required',Rule::in(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'])],'start_time'=>'required|date_format:H:i','end_time'=>'required|date_format:H:i|after:start_time','status'=>['required',Rule::in(['draft','published','archived'])]]);if(empty($d['subject_id'])&&empty($d['custom_name'])){throw ValidationException::withMessages(['subject_id'=>['Either subject_id or custom_name is required.']]);}$q=ClassSchedule::where('day',$d['day'])->where('start_time','<',$d['end_time'])->where('end_time','>',$d['start_time'])->where(fn($w)=>$w->where('room_id',$d['room_id'])->orWhere('section_id',$d['section_id'])->orWhere('instructor_name',$d['instructor_name']));if($ignore)$q->where('id','!=',$ignore->id);if($q->exists())throw ValidationException::withMessages(['schedule_conflict'=>['This time overlaps another schedule using the same room, section, or instructor.']]);return $d;}public function store(Request $r){$s=ClassSchedule::create($this->validated($r));return response()->json($s->load(['subject','section','room']),201);}public function update(Request $r,ClassSchedule $schedule){$schedule->update($this->validated($r,$schedule));return $schedule->fresh()->load(['subject','section','room']);}public function updateStatus(Request $r,ClassSchedule $schedule){$d=$r->validate(['status'=>['required',Rule::in(['draft','published','archived'])]]);$schedule->update($d);return $schedule->fresh()->load(['subject','section','room']);}public function destroy(ClassSchedule $schedule){$schedule->delete();return response()->json(['message'=>'Schedule deleted.']);}}
